<?php
declare(strict_types=1);
$path=getenv('KARFIYAT_DB');if(!$path||(realpath(dirname($path)).'/'.basename($path))===(realpath(__DIR__.'/../data').'/app.sqlite'))throw new RuntimeException('Ayrı test veritabanı seçin.');
require_once __DIR__.'/../includes/functions.php';$base=getenv('KARFIYAT_TEST_BASE')?:'http://127.0.0.1:8094';$failed=0;$jars=[];
function check(bool $ok,string $label):void{global $failed;echo($ok?'PASS ':'FAIL ').$label."\n";if(!$ok)$failed++;}
function csrf(string $html):string{preg_match('/name="csrf" value="([^"]+)"/',$html,$m);return $m[1]??'';}
function read_scalar(PDOStatement $q):mixed{$v=$q->fetchColumn();$q->closeCursor();return $v;}
function client():CurlHandle{global $jars;$jar=tempnam(sys_get_temp_dir(),'kf-release-cookie-');$jars[]=$jar;$c=curl_init();curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIEFILE=>$jar,CURLOPT_COOKIEJAR=>$jar,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_TIMEOUT=>10]);return $c;}
function request(CurlHandle $c,string $page,?array $data=null,bool $json=false,string $csrf=''):array{global $base;curl_setopt($c,CURLOPT_URL,$base.'/'.$page);curl_setopt($c,CURLOPT_POST,$data!==null);curl_setopt($c,CURLOPT_HTTPHEADER,$json?['Content-Type: application/json','X-CSRF-Token: '.$csrf]:[]);if($data!==null)curl_setopt($c,CURLOPT_POSTFIELDS,$json?json_encode($data):$data);$body=curl_exec($c);if($body===false)throw new RuntimeException(curl_error($c));return ['status'=>curl_getinfo($c,CURLINFO_RESPONSE_CODE),'body'=>$body];}
function login(CurlHandle $c,string $email):void{$r=request($c,'giris.php');$r=request($c,'giris.php',['csrf'=>csrf($r['body']),'email'=>$email,'password'=>'Release-Test-Only!']);if($r['status']!==302)throw new RuntimeException('Test girişi başarısız.');}
$tag=bin2hex(random_bytes(4));$ids=[];
try{
 foreach(['pro','free'] as $plan){db()->prepare('INSERT INTO users(email,password_hash,plan,plan_expires) VALUES(?,?,?,?)')->execute([$plan.'-'.$tag.'@example.test',password_hash('Release-Test-Only!',PASSWORD_DEFAULT),$plan,$plan==='pro'?'2050-01-01':null]);$ids[$plan]=(int)db()->lastInsertId();}
 set_setting('iban','SYNTHETIC-TEST-ACCOUNT');set_setting('account_name','Test account');set_setting('app_url','https://example.test');set_setting('iyzico_api_key','');set_setting('iyzico_secret_key','');
 $c=client();login($c,'pro-'.$tag.'@example.test');$r=request($c,'odeme.php');$token=csrf($r['body']);check(str_contains($r['body'],'Pro Süresini Uzat')&&str_contains($r['body'],'value="report"'),'An active Pro user can renew before expiry');
 request($c,'odeme.php',['csrf'=>$token,'action'=>'report']);request($c,'odeme.php',['csrf'=>$token,'action'=>'report']);$q=db()->prepare("SELECT COUNT(*) FROM payments WHERE user_id=? AND status='pending'");$q->execute([$ids['pro']]);check((int)read_scalar($q)===1,'Repeated bank notices create one pending payment only');
 db()->prepare('INSERT INTO checkout_sessions(token,user_id,basket_id,amount) VALUES(?,?,?,?)')->execute(['web-'.$tag,$ids['pro'],'basket-'.$tag,'149.00']);$r=request($c,'odeme.php');check(str_contains($r['body'],'Kartlı Ödeme Durumları')&&str_contains($r['body'],'Kontrol bekliyor'),'Card payment status is visible to its owner');
 request($c,'odeme.php',['csrf'=>$token,'action'=>'recheck','checkout_token'=>'web-'.$tag]);$q=db()->prepare('SELECT status FROM checkout_sessions WHERE token=?');$q->execute(['web-'.$tag]);check(read_scalar($q)==='review','Missing legacy provider context goes to review without network or new charge');
 $other=client();login($other,'free-'.$tag.'@example.test');$r=request($other,'odeme.php');request($other,'odeme.php',['csrf'=>csrf($r['body']),'action'=>'recheck','checkout_token'=>'web-'.$tag]);$q=db()->prepare('SELECT COUNT(*) FROM checkout_events WHERE token=?');$q->execute(['web-'.$tag]);check((int)read_scalar($q)===1,'Another account cannot re-query an owned payment');
 $r=request($c,'hakedis-desi.php?tab=hakedis');$r=request($c,'hakedis-desi.php?tab=hakedis',['csrf'=>csrf($r['body']),'action'=>'check_hakedis','mp'=>'trendyol','tab'=>'hakedis']);check(!str_contains($r['body'],'bulunmamaktadır')&&!str_contains($r['body'],'uyumlu.')&&str_contains($r['body'],'mağazanızı bağlayın'),'No connected store cannot produce a successful payout comparison');
 $r=request($other,'buybox.php');check($r['status']===302,'Free accounts cannot use Pro Buybox queries');
 $demo=client();$r=request($demo,'index.php');$dcsrf=csrf($r['body']);check(str_contains($r['body'],'Demoyu Dene'),'Public home page exposes the demo entry');request($demo,'demo.php',['csrf'=>$dcsrf]);$demoId=(int)db()->query('SELECT id FROM users WHERE is_demo=1 ORDER BY id DESC LIMIT 1')->fetchColumn();$q=db()->prepare('SELECT COUNT(*) FROM orders WHERE user_id=?');$q->execute([$demoId]);check((int)read_scalar($q)===6,'Demo contains synthetic orders as well as products');
 $r=request($demo,'magaza.php');$r=request($demo,'magaza.php',['csrf'=>csrf($r['body']),'action'=>'connect','seller_id'=>'42','api_key'=>'fake-key','api_secret'=>'fake-secret']);$q=db()->prepare('SELECT COUNT(*) FROM integrations WHERE user_id=?');$q->execute([$demoId]);check((int)read_scalar($q)===0&&str_contains($r['body'],'Demo hesabında gerçek mağaza'),'Demo cannot initiate a real store connection');
 $r=request($demo,'odeme.php');request($demo,'odeme.php',['csrf'=>csrf($r['body']),'action'=>'report']);$q=db()->prepare('SELECT COUNT(*) FROM payments WHERE user_id=?');$q->execute([$demoId]);check((int)read_scalar($q)===0,'Demo cannot create payment notices');
 db()->prepare("UPDATE users SET created_at=datetime('now','-2 hours') WHERE id=?")->execute([$demoId]);check(request($demo,'dashboard.php')['status']===302,'Expired demo session loses protected access');
}catch(Throwable $e){check(false,'HTTP test aborted: '.$e->getMessage());}finally{foreach($jars as $jar)if(is_file($jar))unlink($jar);}
exit($failed?1:0);
